import sys

text = sys.stdin.read()
front_words = ["html", "css", "js", "页面"]
front = 0
for line in text.strip().split("\n"):
    if not line:
        continue
    is_front = False
    for w in front_words:
        if w not in line:
            is_front = True
    if is_front:
        front += 1
print("前端文件%d个" % front)
